// Verify current V2 evidence generated by the local fresh-context Playwright QA.
import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
const read=async name=>JSON.parse(await fs.readFile(new URL(name,import.meta.url),'utf8'));
const manifest=await read('manifest.json'),build=await read('build-report.json');
assert.equal(build.pixiCopies,1);assert.equal(build.gsapCopies,1);assert.equal(build.liveEnabled,false);
assert.equal(manifest.runtimeRegistration,false);assert.equal(manifest.deployed,false);
assert.equal(manifest.summary.bodyFrames,40);assert.equal(manifest.summary.effectFrames,84);assert.equal(manifest.summary.cinematicFrames,4);
for(const size of ['desktop','mobile']){
 const r=await read('qa/'+size+'-runtime.json');assert.equal(r.assetVersion,manifest.version);assert.equal(r.runtimeBundle,build.bundleSha256);
 assert.equal(r.passed,true,size+': '+r.errors.join(', '));assert.equal(r.muted,true);assert.equal(r.overflow,false);
 assert.equal(r.browserErrors.length,0);assert.equal(r.failedResponses.length,0);
 assert.equal(r.stopped.registeredTimelines,0);assert.equal(r.stopped.visibleEffects,0);assert.equal(r.stopped.visibleGhosts,0);assert.equal(r.stopped.cinematicVisible,false);
 assert.equal(r.cinematic.cinematicVisible,true);
 assert.equal(r.snapshots.length,5);for(const s of r.snapshots){assert.equal(s.bladeContact.intersects,true);assert(s.groundError<1e-6);assert.equal(s.airborne,false);assert.equal(s.motionPlaybackRate,2);assert.equal(s.effectPlaybackRate,1);assert.equal(s.referenceHeight,610);}
 for(const s of r.speeds){assert(s.advance>0);assert.equal(s.pausedStable,true);}
 assert.equal(r.speedContracts.slashDuration,.48);assert.equal(r.speedContracts.ultimateDuration,1.45);
 assert.equal(r.cleanup.disposed,true);assert.equal(r.cleanup.registeredTimelines,0);assert.equal(r.cleanup.cinemaDestroyed,true);
}
const video=await fs.readFile(new URL('review-v2.webm',import.meta.url));assert(video.length>100000);assert.equal(video.subarray(0,4).toString('hex'),'1a45dfa3');
console.log('V2 verified: PC/mobile five blade contacts, ground, body 2x / FX 1x, four review speeds, awakening cut-in, pause/cancel/disposal, muted video, one shared V3 renderer.');
